tool.command:
ln -s $input_results_npz_path ./input_results_npz_path.$input_results_npz_path.ext; ln -s $input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext; #if $input_topology_path: ln -s $input_topology_path ./input_topology_path.$input_topology_path.ext; #end if #if $config_json: ln -s $config_json ./config_json.$config_json.ext; #end if
feat2traj
#if $config_json: --config ./config_json.$config_json.ext #end if
--input_results_npz_path ./input_results_npz_path.$input_results_npz_path.ext --input_stats_pt_path ./input_stats_pt_path.$input_stats_pt_path.ext #if $input_topology_path: --input_topology_path ./input_topology_path.$input_topology_path.ext #end if --output_traj_path $outname_output_traj_path #if $outname_output_top_path: --output_top_path $outname_output_top_path #end if ;
mv $outname_output_traj_path $output_traj_path; if test -f $outname_output_top_path; then mv $outname_output_top_path $output_top_path; fi;
